     open(); aim(3,220); keys['KeyQ']=false; wheelRelease();
     if(g.msel!=='medkit'&&!(p.hand&&p.hand.k==='medkit')) bad.push('FIVE: letting go on the medkit left the heal pick on '+g.msel);
