     try{ mouse.down=false; keys={}; var g2=__state(); if(g2){ g2.wheel=null; if(!g2.over){ g2.player.iv=0; g2.msel=undefined; __endRaid('abandon'); } } }catch(_e){}
     __topClear(); __resetCfg(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
